package com.myassist.customer.ui;
import android.content.Intent; import android.os.Bundle; import android.view.View; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import com.myassist.customer.MyAssistApp; import com.myassist.customer.network.*; import org.json.JSONObject;
public class RegisterActivity extends AppCompatActivity { EditText name,phone,pass; TextView error; ProgressBar progress; protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_register);name=findViewById(R.id.etName);phone=findViewById(R.id.etPhone);pass=findViewById(R.id.etPass);error=findViewById(R.id.tvError);progress=findViewById(R.id.progress);findViewById(R.id.btnRegister).setOnClickListener(v->register());findViewById(R.id.tvGoLogin).setOnClickListener(v->finish());} void register(){JSONObject j=new JSONObject();try{j.put("full_name",name.getText().toString().trim());j.put("phone",phone.getText().toString().trim());j.put("password",pass.getText().toString());j.put("role","CUSTOMER");}catch(Exception ignored){}progress.setVisibility(View.VISIBLE);ApiService.run(ApiService.post("api/v1/auth/register",j),x->x,new ApiService.Callback<JSONObject>(){public void onSuccess(JSONObject o){MyAssistApp.session().save(o.optString("access_token"),o.optInt("user_id"),o.optString("role"),o.optString("full_name"));runOnUiThread(()->{startActivity(new Intent(RegisterActivity.this,HomeActivity.class));finish();});}public void onError(ApiClient.ApiException e){runOnUiThread(()->{progress.setVisibility(View.GONE);error.setText(e.userMessage);error.setVisibility(View.VISIBLE);});}});} }